CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE "Module" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "IsActive" boolean NOT NULL,
    "Order" integer NOT NULL,
    CONSTRAINT "PK_Module" PRIMARY KEY ("Id")
);

CREATE TABLE "OutboxMessage" (
    "Id" uuid NOT NULL,
    "Name" text NOT NULL,
    "Content" text NOT NULL,
    "CreatedOnUtc" timestamp with time zone NOT NULL,
    "ProcessedOnUtc" timestamp with time zone,
    "Error" text,
    CONSTRAINT "PK_OutboxMessage" PRIMARY KEY ("Id")
);

CREATE TABLE "Role" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_Role" PRIMARY KEY ("Id")
);

CREATE TABLE "Tenant" (
    "Id" uuid NOT NULL,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "ConnectionString" text,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_Tenant" PRIMARY KEY ("Id")
);

CREATE TABLE "User" (
    "Id" uuid NOT NULL,
    "Login" text NOT NULL,
    "Password" text NOT NULL,
    "FullName" text NOT NULL,
    "CellPhone" text,
    "Email" text,
    "SelectedStoreId" uuid NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_User" PRIMARY KEY ("Id")
);

CREATE TABLE "Feature" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "ModuleId" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "Order" integer NOT NULL,
    CONSTRAINT "PK_Feature" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Feature_Module_ModuleId" FOREIGN KEY ("ModuleId") REFERENCES "Module" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Owner" (
    "Id" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "Description" text NOT NULL,
    "Guest" boolean NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_Owner" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Owner_User_UserId" FOREIGN KEY ("UserId") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "UserRole" (
    "UserId" uuid NOT NULL,
    "RoleId" integer NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_UserRole" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_UserRole_Role_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Role" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_UserRole_User_UserId" FOREIGN KEY ("UserId") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Store" (
    "Id" uuid NOT NULL,
    "Name" text NOT NULL,
    "Address" text,
    "Description" text,
    "Approved" boolean NOT NULL,
    "OwnerId" uuid NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_Store" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Store_Owner_OwnerId" FOREIGN KEY ("OwnerId") REFERENCES "Owner" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "StoreFeature" (
    "StoreId" uuid NOT NULL,
    "FeatureId" integer NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_StoreFeature" PRIMARY KEY ("StoreId", "FeatureId"),
    CONSTRAINT "FK_StoreFeature_Feature_FeatureId" FOREIGN KEY ("FeatureId") REFERENCES "Feature" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StoreFeature_Store_StoreId" FOREIGN KEY ("StoreId") REFERENCES "Store" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "StoreRoleFeature" (
    "StoreId" uuid NOT NULL,
    "RoleId" integer NOT NULL,
    "FeatureId" integer NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_StoreRoleFeature" PRIMARY KEY ("StoreId", "RoleId", "FeatureId"),
    CONSTRAINT "FK_StoreRoleFeature_Feature_FeatureId" FOREIGN KEY ("FeatureId") REFERENCES "Feature" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StoreRoleFeature_Role_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Role" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StoreRoleFeature_Store_StoreId" FOREIGN KEY ("StoreId") REFERENCES "Store" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "StoreUser" (
    "UserId" uuid NOT NULL,
    "StoreId" uuid NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_StoreUser" PRIMARY KEY ("UserId", "StoreId"),
    CONSTRAINT "FK_StoreUser_Store_StoreId" FOREIGN KEY ("StoreId") REFERENCES "Store" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StoreUser_User_UserId" FOREIGN KEY ("UserId") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

