ALTER TABLE "Store" ADD "PaymentStartDate" date NOT NULL DEFAULT DATE '-infinity';

CREATE TABLE "ReSeller" (
    "Id" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "Approved" boolean NOT NULL,
    "DiscountPrice" real NOT NULL,
    "PercentDiscountPrice" real NOT NULL,
    "Description" text NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_ReSeller" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ReSeller_User_UserId" FOREIGN KEY ("UserId") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "StorePaymentStatus" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    CONSTRAINT "PK_StorePaymentStatus" PRIMARY KEY ("Id")
);

CREATE TABLE "SystemConfiguration" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Value" text NOT NULL,
    CONSTRAINT "PK_SystemConfiguration" PRIMARY KEY ("Id")
);

CREATE TABLE "ReSellerOwner" (
    "ReSellerId" uuid NOT NULL,
    "OwnerId" uuid NOT NULL,
    "DiscountPrice" real NOT NULL,
    "PercentDiscountPrice" real NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_ReSellerOwner" PRIMARY KEY ("ReSellerId", "OwnerId"),
    CONSTRAINT "FK_ReSellerOwner_Owner_OwnerId" FOREIGN KEY ("OwnerId") REFERENCES "Owner" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ReSellerOwner_ReSeller_ReSellerId" FOREIGN KEY ("ReSellerId") REFERENCES "ReSeller" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "StorePayment" (
    "Id" uuid NOT NULL,
    "StoreId" uuid NOT NULL,
    "StorePaymentStatusId" integer NOT NULL,
    "PaidDate" timestamp with time zone,
    "NotificationDate" timestamp with time zone,
    "PaymentBeforeDate" timestamp with time zone NOT NULL,
    "Price" real NOT NULL,
    "Year" integer NOT NULL,
    "Month" integer NOT NULL,
    "TenantId" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedDate" timestamp with time zone NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "UpdatedDate" timestamp with time zone,
    "UpdatedBy" uuid,
    CONSTRAINT "PK_StorePayment" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StorePayment_StorePaymentStatus_StorePaymentStatusId" FOREIGN KEY ("StorePaymentStatusId") REFERENCES "StorePaymentStatus" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StorePayment_Store_StoreId" FOREIGN KEY ("StoreId") REFERENCES "Store" ("Id") ON DELETE RESTRICT
);

